import json

def transform(grid):
    """Apply the ARC-like transformation."""
    h, w = len(grid), len(grid[0])
    new_grid = [[cell for cell in row] for row in grid]

    # Rule 1: Increment bottom row
    new_grid[h-1] = [(c + 1) % 10 for c in new_grid[h-1]]

    # Rule 2: Find isolated pixels (global: not the most frequent value in the whole grid)
    all_counts = {}
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            all_counts[v] = all_counts.get(v, 0) + 1
    if all_counts:
        most_freq = max(all_counts, key=all_counts.get)

    # Find isolated pixels (non-zero, not equal to most frequent)
    isolated_pixels = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != most_freq and grid[r][c] > 0:
                isolated_pixels.append((r, c))

    # Rule 3: Transform isolated pixels (subtract 3)
    for r, c in isolated_pixels:
        val = grid[r][c]
        new_grid[r][c] = (val - 3) % 10

    # Rule 4: Add vertical line of transformed value at each isolated pixel's column
    # spanning from row 0 to row h-1
    for r, c in isolated_pixels:
        val = new_grid[r][c]  # already transformed
        # Don't overwrite existing features (bars) at the boundaries
        # Vertical line goes from top to bottom
        for rr in range(h):
            if not ((rr == 0) or (rr == h-1)):  # skip boundary rows (handled separately)
                if grid[rr][c] == most_freq:  # only fill background areas
                    new_grid[rr][c] = val

    return new_grid

