    if k not in G and all(len(r) == w_dim and all(x.isdigit() for x in r) for r in rows):
        G[k] = [[int(x) for x in r] for r in rows]

def predict_output(grid):
    h, w = len(grid), len(grid[0])
    new_grid = [[grid[r][c] for c in range(w)] for r in range(h)]

    # Background color
    counts = {}
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)

    # Special pixels: isolated non-bg (not connected horizontally to other non-bg)
    special = []
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v != bg:
                left_ok = c <= 0 or grid[r][c-1] == bg
                right_ok = c >= w-1 or grid[r][c+1] == bg
                if left_ok and right_ok:
                    special.append((r, c))

    # Transform special
    special_vals = {}
    for r, c in special:
        special_vals[(r,c)] = (grid[r][c] - 3) % 10
        new_grid[r][c] = special_vals[(r,c)]

    # Get bottom bar info - find where it STARTS (first non-bg from left)
    last_row = grid[h-1]
    bottom_start = None
    for c in range(w):
        if last_row[c] != bg:
            bottom_start = c
            break

    print(f"Bottom start (first non-bg): {bottom_start}")

    # Calculate vertical line position
    # Demo 1: bottom_start=13, vertical=18 → 13+5=18 ✓
    # Demo 2: bottom_start=19, vertical=24 → 19+5=24 ✓
    vertical_col = bottom_start + 5 if bottom_start is not None else w - 4
    vertical_col = min(max(0, vertical_col), w-1)  # Clamp to bounds

    print(f"Vertical column: {vertical_col}")

    # Value to draw: same as transformed special pixel
    if special:
        line_val = list(special_vals.values())[0]
    elif last_row:
        # Try to derive from a special-like value
        for v in last_row:
            if v != bg:
                line_val = (v - 3) % 10
                break
        else:
            line_val = 0
    else:
        line_val = 0

    print(f"Line value: {line_val}")

    # Fill vertical line from top to just before bottom row
    for rr in range(h-1):
        if grid[rr][vertical_col] == bg:
            new_grid[rr][vertical_col] = line_val

    return new_grid

